type Atoms = Vec<(String, String, [f64; 3])>;

struct Reference {
    id: String,
    name: String,
    ideal: Atoms,
    model: Atoms,
}

fn references() -> Vec<Reference> {
    let mut references: Vec<Reference> = Vec::new();
    for line in REFERENCES.lines() {
        if let Some(header) = line.strip_prefix("## ") {
            let fields = header.split('\t').collect::<Vec<_>>();
            assert_eq!(fields.len(), 3, "{line}");
            assert_eq!(fields[1].len(), 64, "SHA-256 of {}", fields[0]);
            references.push(Reference {
                id: fields[0].into(),
                name: fields[2].into(),
                ideal: Vec::new(),
                model: Vec::new(),
            });
            continue;
        }
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let fields = line.split('\t').collect::<Vec<_>>();
        let reference = references.last_mut().expect("a component line comes first");
        assert_eq!(fields[0], reference.id);
        let position = [fields[4], fields[5], fields[6]].map(|value| value.parse().unwrap());
        let atom = (fields[2].to_string(), fields[3].to_string(), position);
        match fields[1] {
            "ideal" => reference.ideal.push(atom),
            "model" => reference.model.push(atom),
            other => panic!("unknown coordinate set {other}"),
        }
    }
    references
}

fn hetatm(
    serial: usize,
    atom: &str,
    residue: &str,
    sequence: usize,
    element: &str,
    position: [f64; 3],
) -> String {
    let atom = if atom.len() < 4 {
        format!(" {atom:<3}")
    } else {
        atom.to_string()
    };
    format!(
        "HETATM{serial:5} {atom:<4} {residue:>3} A{sequence:4}    {:8.3}{:8.3}{:8.3}  1.00  0.00          {element:>2}",
        position[0], position[1], position[2]
    )
}

/// One residue as PDB text; `mirror` reflects it through the yz plane.
fn pdb(atoms: &Atoms, residue: &str, mirror: bool) -> String {
    let mut lines = atoms
        .iter()
        .enumerate()
        .map(|(index, (name, element, position))| {
            let mut position = *position;
            if mirror {
                position[0] = -position[0];
            }
            hetatm(index + 1, name, residue, 1, element, position)
        })
        .collect::<Vec<_>>();
    lines.push("END".into());
    lines.join("\n") + "\n"
}

fn read(text: &str, policy: NamePolicy) -> Result<PdbReading, PdbError> {
    read_glycans_from_str(text, false, &PdbReadOptions::with_policy(policy))
}

/// The UniqueRES of a one-residue reading.
fn single(reading: &PdbReading) -> String {
    assert_eq!(reading.glycans.len(), 1, "{:?}", reading.glycans);
    let wurcs = write_wurcs(&reading.glycans[0].graph).unwrap();
    let body = wurcs
        .strip_prefix("WURCS=2.0/1,1,0/[")
        .and_then(|rest| rest.strip_suffix("]/1/"))
        .unwrap_or_else(|| panic!("not one residue: {wurcs}"));
    body.to_string()
}

fn contradictions(reading: &PdbReading) -> Vec<String> {
    reading
        .warnings
        .iter()
        .filter(|warning| warning.kind == PdbWarningKind::NameContradictsCoordinates)
        .flat_map(|warning| warning.aspects.clone())
        .collect()
}

fn mirrored(unique: &str) -> String {
    let graph = parse_wurcs(&format!("WURCS=2.0/1,1,0/[{unique}]/1/")).unwrap();
    let mut graph = graph;
    let root = graph.root().unwrap();
    let residue = graph.residue_mut(root).unwrap();
    residue.skeleton_code = mirror_skeleton_code(&residue.skeleton_code);
    single_from_wurcs(&write_wurcs(&graph).unwrap())
}

fn single_from_wurcs(wurcs: &str) -> String {
    wurcs
        .strip_prefix("WURCS=2.0/1,1,0/[")
        .and_then(|rest| rest.strip_suffix("]/1/"))
        .unwrap()
        .to_string()
}

#[test]
fn the_reference_table_covers_every_expected_component_and_nothing_else() {
    let references = references();
    let mut found = references
        .iter()
        .map(|reference| reference.id.as_str())
        .collect::<Vec<_>>();
    found.sort_unstable();
    let mut expected = EXPECTED.iter().map(|(id, _)| *id).collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(found, expected);
    for reference in &references {
        assert!(!reference.name.is_empty(), "{}", reference.id);
        assert!(reference.ideal.len() >= 9, "{}", reference.id);
        assert!(reference.model.len() >= 9, "{}", reference.id);
    }
}

#[test]
fn ccd_components_are_read_from_their_coordinates_whatever_they_are_called() {
    for reference in references() {
        let expected = EXPECTED
            .iter()
            .find(|(id, _)| *id == reference.id)
            .unwrap()
            .1;
        for (set, atoms) in [("ideal", &reference.ideal), ("model", &reference.model)] {
            // The model coordinates of GU2 lack O4 (the linked oxygen of the
            // entry they come from); without hydrogens or a name nothing
            // says it is missing.
            if atoms.len() < reference.ideal.len() {
                continue;
            }
            let context = format!("{} ({}) {set}", reference.id, reference.name);
            // The model coordinates of GZL are planar at C2, C3 and C5
            // (normalised volumes -0.02, 0.06, -0.06; C2-C3 1.33 Å): the
            // coordinates cannot decide them, and only a name can.
            if (reference.id.as_str(), set) == ("GZL", "model") {
                let reading = read(&pdb(atoms, "LIG", false), NamePolicy::Coordinates).unwrap();
                assert_eq!(single(&reading), "axx1xh-1x_1-4", "{context}");
                assert!(
                    reading
                        .warnings
                        .iter()
                        .all(|warning| warning.kind == PdbWarningKind::DistortedGeometry)
                );
                let reading = read(&pdb(atoms, "GZL", false), NamePolicy::Strict).unwrap();
                assert_eq!(single(&reading), expected, "{context}, named GZL");
                assert_eq!(
                    reading.warnings[0].kind,
                    PdbWarningKind::DistortedGeometry,
                    "{context}"
                );
                assert_eq!(reading.warnings[0].positions, vec![1, 2, 3, 5], "{context}");
                continue;
            }
            // A neutral name: the coordinates alone.
            let reading = read(&pdb(atoms, "LIG", false), NamePolicy::Coordinates).unwrap();
            assert_eq!(single(&reading), expected, "{context}, named LIG");
            assert!(
                reading.warnings.is_empty(),
                "{context}: {:?}",
                reading.warnings
            );
            assert_eq!(
                reading.residues[0].from_coordinates.as_deref(),
                Some(expected),
                "{context}"
            );
            // Its own name agrees with the coordinates.
            if reference.id.len() == 3 {
                let reading = read(&pdb(atoms, &reference.id, false), NamePolicy::Strict).unwrap();
                assert_eq!(single(&reading), expected, "{context}, named itself");
                assert!(contradictions(&reading).is_empty(), "{context}");
            }
            // The mirror image is the enantiomer, under any name.
            let enantiomer = mirrored(expected);
            for name in ["LIG", reference.id.as_str()] {
                if name.len() != 3 {
                    continue;
                }
                let reading = read(&pdb(atoms, name, true), NamePolicy::Coordinates).unwrap();
                assert_eq!(
                    single(&reading),
                    enantiomer,
                    "{context}, mirrored, named {name}"
                );
            }
        }
    }
}

#[test]
fn a_misleading_name_is_reported_and_the_coordinates_decide() {
    let references = references();
    let atoms = |id: &str| {
        references
            .iter()
            .find(|reference| reference.id == id)
            .unwrap_or_else(|| panic!("no reference {id}"))
            .ideal
            .clone()
    };
    // (coordinates, residue name, what the name contradicts)
    let cases: &[(&str, &str, &[&str])] = &[
        // α-L-IdoA: GLYCAM writes L in lower case (`u`), D in upper case.
        ("IDR", "0uA", &[]),
        ("IDR", "4uA", &[]),
        ("IDR", "0UA", &["C2", "C3", "C4", "C5"]),
        ("IDR", "0uB", &["anomer"]),
        ("IDR", "IDR", &[]),
        ("IDR", "IDS", &[]),
        ("IDR", "LGU", &["C2"]),
        ("IDR", "LIG", &[]),
        // α-L-GulA2S under IdoA names: the CHARMM-GUI heparan sulfate case.
        ("IDX", "IDS", &["C2"]),
        ("LGU", "IDR", &["C2"]),
        ("LGU", "2uA", &["C2"]),
        // α-L-Fuc
        ("FUC", "0fA", &[]),
        ("FUC", "0FA", &["C2", "C3", "C4", "C5"]),
        ("FUC", "0fB", &["anomer"]),
        ("FUC", "FUC", &[]),
        ("FUC", "FUL", &["anomer"]),
        ("FUC", "FCA", &["C2", "C3", "C4", "C5"]),
        ("FCA", "0FA", &[]),
        ("FCA", "0fA", &["C2", "C3", "C4", "C5"]),
        // α-L-Rha
        ("RAM", "0hA", &[]),
        ("RAM", "0HA", &["C2", "C3", "C4", "C5"]),
        ("RAM", "RAM", &[]),
        ("RAM", "0fA", &["C2", "C4"]),
        // α-L-Araf
        ("AHR", "0aD", &[]),
        ("AHR", "0AD", &["C2", "C3", "C4"]),
        ("AHR", "0aU", &["anomer"]),
        ("AHR", "AHR", &[]),
        ("AHR", "ARA", &["ring"]),
        ("AHR", "0aA", &["ring"]),
        // β-D-Gul
        ("GL0", "0KB", &[]),
        ("GL0", "0kB", &["C2", "C3", "C4", "C5"]),
        ("GL0", "0KA", &["anomer"]),
        ("GL0", "GL0", &[]),
        ("GL0", "0GB", &["C3", "C4"]),
        // Glc, Gal, Man
        ("GLC", "0GA", &[]),
        ("GLC", "0gA", &["C2", "C3", "C4", "C5"]),
        ("GLC", "0GB", &["anomer"]),
        ("GLC", "0LA", &["C4"]),
        ("GLC", "0MA", &["C2"]),
        ("GLC", "BGC", &["anomer"]),
        ("GLC", "GLA", &["C4"]),
        ("GLC", "MAN", &["C2"]),
        ("GAL", "0LB", &[]),
        ("GAL", "0lB", &["C2", "C3", "C4", "C5"]),
        ("GAL", "BGC", &["C4"]),
        ("MAN", "0MA", &[]),
        ("MAN", "0mA", &["C2", "C3", "C4", "C5"]),
        ("MAN", "BMA", &["anomer"]),
        // Sialic acid, ketose
        ("SIA", "0SA", &[]),
        ("SIA", "SLB", &["anomer"]),
        ("FRU", "0CU", &[]),
        ("FRU", "0CD", &["anomer"]),
    ];
    for &(component, name, contradicted) in cases {
        let expected = EXPECTED.iter().find(|(id, _)| *id == component).unwrap().1;
        let text = pdb(&atoms(component), name, false);
        let context = format!("{component} coordinates named {name}");
        let reading = read(&text, NamePolicy::Coordinates).unwrap();
        assert_eq!(single(&reading), expected, "{context}");
        assert_eq!(contradictions(&reading), contradicted, "{context}");

        let strict = read(&text, NamePolicy::Strict);
        if contradicted.is_empty() {
            assert_eq!(single(&strict.unwrap()), expected, "{context}");
        } else {
            let Err(PdbError::NamesContradictCoordinates(warnings)) = strict else {
                panic!("{context}: strict reading did not fail");
            };
            assert!(!warnings.is_empty(), "{context}");
        }

        // The names policy keeps what the name says where it says something.
        let names = read(&text, NamePolicy::Names).unwrap();
        if contradicted.is_empty() {
            assert_eq!(single(&names), expected, "{context}");
        } else {
            let from_name = names.residues[0].from_name.clone().unwrap();
            let named = parse_wurcs(&format!("WURCS=2.0/1,1,0/[{from_name}]/1/")).unwrap();
            let read_back =
                parse_wurcs(&format!("WURCS=2.0/1,1,0/[{}]/1/", single(&names))).unwrap();
            let (named, read_back) = (
                named.residue(named.root().unwrap()).unwrap(),
                read_back.residue(read_back.root().unwrap()).unwrap(),
            );
            assert_eq!(read_back.skeleton_code, named.skeleton_code, "{context}");
            assert_eq!(read_back.ring_end, named.ring_end, "{context}");
            if named.anomeric_symbol != crabwurcs_core::AnomericSymbol::Unknown {
                assert_eq!(
                    read_back.anomeric_symbol, named.anomeric_symbol,
                    "{context}"
                );
            }
        }
    }
}

#[test]
fn a_contradiction_is_reported_in_words() {
    let references = references();
    let gula = &references
        .iter()
        .find(|reference| reference.id == "LGU")
        .unwrap()
        .ideal;
    let reading = read(&pdb(gula, "2uA", false), NamePolicy::Coordinates).unwrap();
    let warning = &reading.warnings[0];
    assert_eq!(warning.kind, PdbWarningKind::NameContradictsCoordinates);
    assert_eq!(warning.named.as_deref(), Some("α-L-IdopA"));
    assert_eq!(warning.coordinates.as_deref(), Some("α-L-GulpA"));
    assert_eq!(warning.positions, vec![2]);
    assert_eq!(
        warning.to_string(),
        "residue 2uA A:1: named α-L-IdopA, coordinates say α-L-GulpA (C2)"
    );
    let Err(error) = read(&pdb(gula, "2uA", false), NamePolicy::Strict) else {
        panic!("strict reading did not fail");
    };
    assert!(
        error
            .to_string()
            .contains("residue 2uA A:1: named α-L-IdopA, coordinates say α-L-GulpA (C2)"),
        "{error}"
    );
}

#[test]
fn readings_report_the_configuration_of_every_centre() {
    let references = references();
    let idoa = &references
        .iter()
        .find(|reference| reference.id == "IDR")
        .unwrap()
        .ideal;
    let reading = read(&pdb(idoa, "0UA", false), NamePolicy::Coordinates).unwrap();
    let residue = &reading.residues[0];
    assert_eq!(residue.ring_atoms, ["O5", "C1", "C2", "C3", "C4", "C5"]);
    assert_eq!(residue.backbone_atoms, ["C1", "C2", "C3", "C4", "C5", "C6"]);
    assert_eq!(residue.from_coordinates.as_deref(), Some("a2121A-1a_1-5"));
    assert_eq!(residue.from_name.as_deref(), Some("a1212A-1a_1-5"));
    let codes = residue
        .centres
        .iter()
        .map(|centre| (centre.atom.as_str(), centre.code))
        .collect::<Vec<_>>();
    // C1 is the side of O1; C2..C5 read L-ido.
    assert_eq!(
        codes,
        [
            ("C1", '1'),
            ("C2", '2'),
            ("C3", '1'),
            ("C4", '2'),
            ("C5", '1')
        ]
    );
    assert!(
        residue
            .centres
            .iter()
            .all(|centre| centre.volume.abs() > 0.5)
    );
}

/// The `_atom_site` rows of a model-1 mmCIF fixture as PDB records, with
/// the residue names and sulfate split of `glycam`.
fn as_glycam_pdb(mmcif: &str, rename: &dyn Fn(&str) -> &'static str) -> String {
    let keys = mmcif
        .lines()
        .filter_map(|line| line.trim().strip_prefix("_atom_site."))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let column = |key: &str| keys.iter().position(|name| name == key).unwrap();
    let (atom, element, residue, sequence, x, y, z) = (
        column("label_atom_id"),
        column("type_symbol"),
        column("label_comp_id"),
        column("auth_seq_id"),
        column("Cartn_x"),
        column("Cartn_y"),
        column("Cartn_z"),
    );
    let mut lines = Vec::new();
    let mut sulfates: Vec<(usize, Atoms)> = Vec::new();
    for row in mmcif
        .lines()
        .filter(|line| line.starts_with("ATOM") || line.starts_with("HETATM"))
    {
        let fields = row.split_whitespace().collect::<Vec<_>>();
        let number: usize = fields[sequence].parse().unwrap();
        let position = [fields[x], fields[y], fields[z]].map(|value| value.parse().unwrap());
        let name = fields[atom];
        // GLYCAM keeps every sulfate in an SO3 residue of its own: S1 with
        // O1S-O3S (N-sulfate or 2-O-sulfate), S2 with O4S-O6S (6-O-sulfate).
        let group = match name {
            "S" | "S1" | "O1S" | "O2S" | "O3S" => Some(1),
            "S2" | "O4S" | "O5S" | "O6S" => Some(2),
            _ => None,
        };
        if let Some(group) = group {
            let key = number * 10 + group;
            let index = match sulfates.iter().position(|(existing, _)| *existing == key) {
                Some(index) => index,
                None => {
                    sulfates.push((key, Vec::new()));
                    sulfates.len() - 1
                }
            };
            sulfates[index]
                .1
                .push((name.to_string(), fields[element].to_string(), position));
            continue;
        }
        lines.push((
            number,
            name.to_string(),
            rename(fields[residue]),
            fields[element].to_string(),
            position,
        ));
    }
    let mut text = Vec::new();
    for (serial, (number, name, residue, element, position)) in lines.iter().enumerate() {
        text.push(
            hetatm(serial + 1, name, residue, *number, element, *position)
                .replacen("HETATM", "ATOM  ", 1),
        );
    }
    let mut serial = lines.len();
    for (offset, (_, atoms)) in sulfates.iter().enumerate() {
        for (name, element, position) in atoms {
            serial += 1;
            text.push(
                hetatm(serial, name, "SO3", 100 + offset, element, *position)
                    .replacen("HETATM", "ATOM  ", 1),
            );
        }
    }
    text.push("END".into());
    text.join("\n") + "\n"
}

const HEPARIN_DODECASACCHARIDE: &str = "WURCS=2.0/2,12,11/[a2122h-1a_1-5_2*NSO/3=O/3=O_6*OSO/3=O/3=O][a2121A-1a_1-5_2*OSO/3=O/3=O]/1-2-1-2-1-2-1-2-1-2-1-2/a4-b1_b4-c1_c4-d1_d4-e1_e4-f1_f4-g1_g4-h1_h4-i1_i4-j1_j4-k1_k4-l1";

#[test]
fn sulfated_heparin_is_one_glycan_read_from_its_coordinates() {
    let reading = read_glycans_from_str(HEPARIN_1HPN, true, &PdbReadOptions::default()).unwrap();
    assert_eq!(reading.glycans.len(), 1);
    assert_eq!(reading.glycans[0].graph.node_count(), 12);
    assert_eq!(
        write_wurcs(&reading.glycans[0].graph).unwrap(),
        HEPARIN_DODECASACCHARIDE
    );
    assert!(reading.warnings.is_empty(), "{:?}", reading.warnings);
    assert_eq!(
        reading.glycans[0].attachment_site.as_deref(),
        Some("A/SGN/1")
    );

    // The same molecule written the GLYCAM way: every sulfate an SO3
    // residue, IdoA2S as `4uA` (L in lower case), GlcNS6S as `4YS`.
    let glycam = as_glycam_pdb(HEPARIN_1HPN, &|name| match name {
        "IDS" => "4uA",
        "SGN" => "4YS",
        other => panic!("unexpected residue {other}"),
    });
    let reading = read(&glycam, NamePolicy::Strict).unwrap();
    assert_eq!(
        reading.glycans.len(),
        1,
        "sulfates must not split the glycan"
    );
    assert_eq!(
        write_wurcs(&reading.glycans[0].graph).unwrap(),
        HEPARIN_DODECASACCHARIDE
    );
    assert!(reading.warnings.is_empty(), "{:?}", reading.warnings);

    // Upper-case `4UA` is D-IdoA in GLYCAM: every IdoA is reported, and the
    // coordinates (L-IdoA2S) decide.
    let glycam = as_glycam_pdb(HEPARIN_1HPN, &|name| match name {
        "IDS" => "4UA",
        "SGN" => "4YS",
        other => panic!("unexpected residue {other}"),
    });
    let reading = read(&glycam, NamePolicy::Coordinates).unwrap();
    assert_eq!(
        write_wurcs(&reading.glycans[0].graph).unwrap(),
        HEPARIN_DODECASACCHARIDE
    );
    assert_eq!(
        reading
            .warnings
            .iter()
            .filter(|warning| warning.kind == PdbWarningKind::NameContradictsCoordinates)
            .count(),
        6
    );
    let names = read(&glycam, NamePolicy::Names).unwrap();
    assert!(
        write_wurcs(&names.glycans[0].graph)
            .unwrap()
            .contains("a1212A-1a_1-5_2*OSO/3=O/3=O"),
        "the names policy keeps D-IdoA2S"
    );
}

#[test]
fn a_crystal_model_with_clashes_and_a_missing_atom_stays_one_glycan() {
    let reading = read_glycans_from_str(HEPARIN_3IRJ, true, &PdbReadOptions::default()).unwrap();
    assert_eq!(reading.glycans.len(), 1);
    assert_eq!(reading.glycans[0].graph.node_count(), 24);
    let wurcs = write_wurcs(&reading.glycans[0].graph).unwrap();
    assert!(wurcs.starts_with(
        "WURCS=2.0/2,24,23/[a2122h-1a_1-5_2*NSO/3=O/3=O_6*OSO/3=O/3=O][a2121A-1a_1-5_2*OSO/3=O/3=O]/"
    ));
    // IDS A:24 has no O4: its C4 is taken from the name.
    assert_eq!(reading.warnings.len(), 1, "{:?}", reading.warnings);
    let warning = &reading.warnings[0];
    assert_eq!(warning.kind, PdbWarningKind::MissingAtoms);
    assert_eq!(
        (warning.residue_name.as_str(), warning.sequence_number),
        ("IDS", 24)
    );
    assert_eq!(warning.positions, vec![4]);
}
